  'journal.addHint': 'In der offenen Periode: eine Abgrenzung, eine Abschreibung, eine Umbuchung, oder eine Bankzahlung, unter «Zahlung» gewählt.',
  'journal.correctionTitle': 'Korrekturbuchung',
  'journal.correctionHint': 'Gebucht in der offenen Periode, deklariert in der {correction} {filed}.',
  'journal.correctionHintUnregistered': "Gebucht in der offenen Periode; {filed} ist abgeschlossen. Die Firma ist nicht steuerpflichtig: keine MWST-Abrechnung, kein MWST-Code.",
  'journal.correctionLead': 'Was war falsch?',
  'journal.correctionAs.vat': 'MWST-Code',
  'journal.correctionAs.account': 'Konto',
  'journal.correctionAs.storno': 'Ganze Buchung',
  'journal.correctionHow.vat': 'Nimmt nur die Steuer von {code} zurück: {account} gegen sich selbst, MWST-Code umgekehrt. Bank und {side} bleiben, die Zahlung ist ja geschehen. Gilt ein anderer Satz, den richtigen Code in einer zweiten Korrektur buchen.',
  'journal.correctionSide.expense': 'Aufwand',
  'journal.correctionSide.revenue': 'Ertrag',
  'journal.correctionHow.account': "Verschiebt den Betrag vom alten auf das richtige Konto: das richtige Konto im leeren Feld eintragen. Die Bank bleibt, die MWST auch, ausser auf dem Privatkonto: privat gibt es keine Vorsteuer, dann nimmt die Korrektur sie zurück.",
  'journal.correctionHowNoInputTax.none': "Verschiebt den Betrag vom alten auf das richtige Konto: das richtige Konto im leeren Feld eintragen. Die Bank bleibt. Die Firma ist nicht steuerpflichtig: die Korrektur trägt keinen MWST-Code, auch aufs Privatkonto nicht.",
  'journal.correctionHowNetRateSale': "Verschiebt den Betrag vom alten auf das richtige Konto: das richtige Konto im leeren Feld eintragen. Die Bank bleibt. War es kein Verkauf (Darlehen, Rückzahlung, privat), geht der Betrag auf ein Konto, das kein Umsatz ist: die Korrektur trägt dann {turned}, und Umsatz und Steuer zum Saldosteuersatz verlassen die eingereichte Abrechnung. Auf ein anderes Umsatzkonto bleibt {code}.",
  'journal.correctionNoSale': "{account} ist kein Umsatzkonto: der Verkauf war keiner. Die Korrektur trägt {code}: in der Korrekturabrechnung gehen der Umsatz von CHF {amount} und die Steuer von CHF {tax} zum Saldosteuersatz zurück.",
  'journal.correctionHowNoInputTax.net-rate': "Verschiebt den Betrag vom alten auf das richtige Konto: das richtige Konto im leeren Feld eintragen. Die Bank bleibt. Mit dem Saldosteuersatz gibt es keine Vorsteuer: die Korrektur trägt keinen Vorsteuer-Code, auch aufs Privatkonto nicht.",
  'journal.correctionHow.claim': "Der Beleg zeigt {rate} % Schweizer MWST, gebucht war {was}: die Korrektur macht die Vorsteuer von CHF {tax} mit {code} nachträglich geltend. Bank und Aufwand bleiben; die Korrekturabrechnung des Quartals weist sie aus.",
  'journal.correctionPrivate': "{account} ist privat: dort gibt es keine Vorsteuer. Die Korrektur nimmt die CHF {tax} Vorsteuer von {was} mit {code} zurück (Eigenverbrauch); die Korrekturabrechnung des Quartals weist sie aus.",
  'journal.correctionPrivateNoInputTax.none': "{account} ist privat. Die Firma ist nicht steuerpflichtig, der Einkauf hat keine Vorsteuer abgezogen: die Korrektur nimmt keine zurück und trägt keinen MWST-Code.",
  'journal.correctionPrivateNoInputTax.net-rate': "{account} ist privat. Mit dem Saldosteuersatz hat der Einkauf keine Vorsteuer abgezogen: die Korrektur nimmt keine zurück und trägt keinen MWST-Code (kein K81-B).",
  'journal.correctionHow.storno': 'Nimmt die ganze Buchung zurück, auch die Bankseite: nur wenn die Zahlung nicht geschehen ist.',
  'journal.movesBank': 'Diese Buchung ändert {account} um {amount}, ohne Zahlung auf dem Kontoauszug: danach stimmen Bücher und Bank nicht mehr überein.',
  'journal.movesBankCorrection': 'Diese Korrektur ändert {account} um {amount}, obwohl die Zahlung auf dem Kontoauszug steht: danach stimmen Bücher und Bank nicht mehr überein. War nur der MWST-Code oder das Konto falsch, oben «MWST-Code» oder «Konto» wählen.',
