  'vatCodes.open': 'Codes erklärt',
  'vatCodes.intro': 'Jede Buchung trägt einen MWST-Code aus der Code-Liste von Banana Buchhaltung. Der Code sagt, in welche Ziffern der MWST-Abrechnung der Betrag fliesst und ob der Betrag die Steuer enthält. Die Ziffern hier kommen aus derselben Rechnung wie die Abrechnung.',
