  'desktop.q.vatRegistered.why': 'Pflicht ab CHF 100’000 Umsatz im Jahr; darunter kann sich eine Firma freiwillig eintragen und ist dann eingetragen. Nur eine eingetragene Firma bucht mit MWST-Codes und rechnet ab.',
  'desktop.q.vatRegistered.yes': 'ja, mit MWST-Nummer',
