  'desktop.q.vatMethod.ask': 'MWST-Methode',
  'desktop.q.vatMethod.why': 'Effektiv: du zahlst die MWST, die du verrechnet hast, abzüglich der MWST auf deinen Einkäufen (Vorsteuer). Saldosteuersatz: ein von der ESTV bewilligter Satz auf dem Umsatz, ohne diesen Abzug.',
  'desktop.q.vatMethod.where': 'Wo steht es? Im ESTV-Portal unter «Neue Geschäfte» deine Firma wählen, dann auf der Karte «Abrechnungsmodalitäten» auf «Anpassen»: dort siehst du deine aktuelle Abrechnungsmethode (du musst nichts ändern). Mit dem Saldosteuersatz rechnet eine Firma ab, die ihn beantragt hat und der die ESTV einen Satz bewilligt hat; abgerechnet wird er mit dem Formular 0553. Ohne Zugang zum Portal: deine Treuhand weiss es. Falsch gewählt? Unter Firma › MWST änderst du es, solange dieses Jahr keine Buchungen hat.',
  'desktop.q.vatMethod.effective': 'effektive Methode',
  'desktop.q.vatMethod.net-rate': 'Saldosteuersatz',
  'desktop.q.vatMethod.net-rate.caveat': 'Verkäufe werden brutto mit dem bewilligten Saldosteuersatz gebucht (einer oder zwei, wie von der ESTV bewilligt), Einkäufe brutto ohne Vorsteuer; die Abrechnung ist das Formular 0553, halbjährlich. Als Nächstes fragt die App nach dem Satz.',
  'desktop.q.basis.ask': 'Abrechnungsart',
  'desktop.q.basis.why': 'Wann die MWST zählt. Vereinnahmt: wenn das Geld fliesst. Vereinbart: wenn du deine Rechnung schreibst, die Vorsteuer, wenn eine Rechnung eintrifft.',
  'desktop.q.basis.where': 'Wo steht es? Im ESTV-Portal unter «Neue Geschäfte» deine Firma wählen, dann auf der Karte «Abrechnungsmodalitäten» auf «Anpassen»: dort siehst du deine aktuelle Abrechnungsart, vereinbart oder vereinnahmt (du musst nichts ändern). Ohne Zugang zum Portal: deine Treuhand weiss es. Falsch gewählt? Unter Firma › MWST änderst du es, solange dieses Jahr keine Buchungen hat.',
  'desktop.q.noVat': 'Wir rechnen keine MWST ab',
  'desktop.more': 'mehr',
  'desktop.q.noVat.hint': '«Wir rechnen keine MWST ab» ist nur für eine Firma, die nicht im MWST-Register steht (Pflicht ist der Eintrag ab CHF 100’000 Umsatz im Jahr, darunter freiwillig): dann werden Käufe, Verkäufe und Rechnungen ohne MWST gebucht. Füllt eure Treuhand die MWST-Abrechnungen aus, ist die Firma eingetragen.',
  'desktop.q.noVat.hintShort': '«Wir rechnen keine MWST ab» nur, wenn die Firma nicht im MWST-Register steht; füllt eure Treuhand MWST-Abrechnungen aus, ist sie eingetragen.',
  'desktop.q.basis.received': 'vereinnahmt',
  'desktop.q.basis.agreed': 'vereinbart',
  'desktop.q.basis.agreed.caveat': 'Eine Rechnung der App wird an ihrem Datum als offene Forderung mit ihrer MWST gebucht, die Zahlung gleicht sie nur aus. Die Vorsteuer einer Lieferantenrechnung zählt am Datum der Rechnung, sobald ihre Zahlung gebucht ist.',
  'desktop.q.basis.agreed.caveat.more': 'Die offenen Forderungen stehen auf Konto 1100.',
  'desktop.q.period.ask': 'Abrechnungsperiode',
  'desktop.q.period.why': 'Wie oft du die MWST abrechnest. Effektive Methode: quartalsweise; Saldosteuersatz: halbjährlich, ausser die ESTV erlaubt anderes.',
  'desktop.q.period.quarterly': 'quartalsweise',
  'desktop.q.period.half-yearly': 'halbjährlich',
  'desktop.q.period.monthly': 'monatlich',
  'desktop.q.period.monthly.unsupported': 'Monatliche Abrechnungen werden noch nicht unterstützt: Abrechnung und Export decken Quartale und Halbjahre ab.',
  'desktop.q.fiscalYear.ask': 'Geschäftsjahr',
  'desktop.q.fiscalYear.why': 'Die Bücher beginnen am 1. Januar; Eröffnungssaldi, Abschluss und Perioden folgen dem Kalenderjahr.',
  'desktop.q.fiscalYear.calendar': 'Kalenderjahr (1.1.–31.12.)',
  'desktop.q.fiscalYear.other': 'anderes',
  'desktop.q.fiscalYear.other.unsupported': 'Ein anderes Geschäftsjahr als das Kalenderjahr wird noch nicht unterstützt: Eröffnungssaldi und Abschluss gelten pro Kalenderjahr.',
  'desktop.q.start.ask': 'Ausgangslage',
  'desktop.q.start.why': 'Beides legt dieselben Bücher an. Bei einem Wechsel trägst du danach ein, was die Firma am 1. Januar hatte (Bank, offene Rechnungen, Schulden), aus der Bilanz des Vorjahres.',
  'desktop.q.start.where': 'Du trägst es später unter Firma › Eröffnung ein; bis dahin kann der Kontostand in der App von dem der Bank abweichen.',
  'desktop.q.start.new': 'neue Firma, leere Bücher',
  'desktop.q.start.switching': 'Wechsel von einer anderen Buchhaltung',
  'desktop.q.start.switching.caveat': 'Bring die Eröffnungssaldi aus deinem bisherigen Programm mit. Liest du den ersten Auszug eines Kontos ein, bietet dir die App seinen Anfangsstand als Eröffnungssaldo an.',
  'desktop.q.sells.ask': 'Was verkauft ihr?',
  'desktop.q.sells.why': 'Bestimmt, wohin Einkäufe und Verkäufe ohne eigene Regel gebucht werden: Material oder Ware zum Weiterverkauf; Erlöse aus eigenen Produkten und Arbeit mit Material, aus Handelsware, aus Dienstleistungen. Jede Kombination geht.',
  'desktop.q.sells.more': 'Die Konten: Material 4000, Ware zum Weiterverkauf 4200; Erlöse aus eigenen Produkten und Arbeit mit Material 3000, aus Handelsware 3200, aus Dienstleistungen 3400.',
  'desktop.q.sells.made': 'eigene Produkte, Arbeit mit Material (Handwerk)',
  'desktop.q.sells.traded': 'eingekaufte Ware (Handel)',
  'desktop.q.sells.services': 'Dienstleistungen',
  'desktop.q.foreignCustomers.ask': 'Kundschaft im Ausland?',
  'desktop.q.foreignCustomers.why': 'Eine Dienstleistung an Kundschaft im Ausland ist meist nicht in der Schweiz steuerbar: eine eingetragene Firma deklariert sie, aber ohne MWST.',
  'desktop.q.foreignCustomers.yes': 'ja',
  'desktop.q.foreignCustomers.no': 'nein',
  'desktop.q.imports.ask': 'Importierst du Waren?',
  'desktop.q.imports.why': 'Importe kommen mit Zoll- und Einfuhrsteuer-Rechnungen des Kuriers, getrennt von der Ware gebucht.',
  'desktop.q.imports.yes': 'ja',
  'desktop.q.imports.no': 'nein',
  'desktop.q.employees.ask': 'Angestellte',
  'desktop.q.employees.why': 'Löhne kommen von deinem Lohnanbieter oder der Treuhand; Vanilla Accounting bucht die Zahlungen, es rechnet keine Löhne.',
  'desktop.q.employees.none': 'keine',
  'desktop.q.employees.owner': 'nur der Inhaber',
  'desktop.q.employees.staff': 'Personal',
  'desktop.q.employees.owner.caveat': 'Vanilla Accounting bucht Lohn und AHV-, BVG- und UVG-Zahlungen; die Lohnabrechnung selbst (Lohnausweis, AHV-Abrechnung) bleibt bei deinem Anbieter.',
  'desktop.q.employees.staff.caveat': 'Vanilla Accounting bucht Lohn und AHV-, BVG- und UVG-Zahlungen; die Lohnabrechnung selbst (Lohnausweis, AHV-Abrechnung) bleibt bei deinem Anbieter.',
  'desktop.q.ownerPaysPrivately.ask': 'Zahlt der Inhaber Geschäftskosten privat?',
  'desktop.q.ownerPaysPrivately.why': 'Dann schuldet die Firma sie ihm zurück: diese Belege gehen auf ein Konto, das festhält, was die Firma dem Inhaber schuldet (Kontokorrent).',
  'desktop.q.ownerPaysPrivately.yes': 'ja',
  'desktop.q.ownerPaysPrivately.no': 'nein',
  'desktop.q.privateUse.ask': 'Private Nutzung von Geschäftsauto oder -telefon',
  'desktop.q.privateUse.why': 'Der private Anteil geht am Jahresende auf den Inhaber; eine Firma mit MWST zahlt damit auch die MWST zurück, die sie auf diesem Anteil abgezogen hat (Eigenverbrauch). Keines gewählt: keine private Nutzung.',
  'desktop.q.privateUse.car': 'Auto',
  'desktop.q.privateUse.phone': 'Telefon',
  'desktop.q.payouts.ask': 'Kommen Verkäufe als Auszahlungen eines Webshops oder Zahlungsanbieters?',
  'desktop.q.payouts.why': 'Eine Auszahlung bündelt Verkäufe und Gebühren; sie läuft über ein eigenes Konto, das festhält, was der Anbieter dir noch schuldet (Durchlaufkonto), damit beides gebucht wird.',
  'desktop.q.payouts.more': 'Das Durchlaufkonto ist 1093.',
  'desktop.q.payouts.yes': 'ja',
  'desktop.q.payouts.no': 'nein',
