  'automation.payouts.clearing': "Kein Umsatz: sie warten auf den Bestellexport von {provider}. Zieh ihn irgendwo auf diese Seite; die App fragt dann nach dem Durchlaufkonto und bucht sie davon ab.",
  'automation.payouts.since': "Kein Umsatz: sie warten auf den Tag, ab dem sie über das Durchlaufkonto {account} gehen. Der Bestellexport von {provider} fragt danach, wenn du ihn irgendwo auf diese Seite ziehst.",
  'automation.payouts.clearingNoSales': "Kein Umsatz: sie warten auf das Durchlaufkonto von {provider}, das die App noch nicht kennt. Die Verkäufe bucht sie aus den Auszahlungsabrechnungen von {provider}.",
