  'runWhy.periodRunning': '{period} läuft noch bis {ends}. Die Abrechnung lässt sich ab dem {from} erstellen: erst dann sind alle Zahlungen der Periode da.',
  'runWhy.periodFiled': '{period} ist eingereicht (abgeschlossen bis {through}) und ändert sich nicht mehr. Eine Korrektur wird in der Korrekturabrechnung dieser Periode deklariert.',
