  'onboarding.change': 'Ändern',
  'onboarding.draft.hello': 'Hallo! Ich richte mit dir deine neue Buchhaltung ein. Jede Antwort schreibe ich gleich in diesen Ordner; hörst du auf, geht es beim nächsten Öffnen genau hier weiter.',
  'onboarding.draft.firm': 'Wie heisst deine Firma, welche UID hat sie und wer führt sie?',
  'onboarding.draft.firmRest': 'Das habe ich von deiner Firma schon. Es fehlt nur noch, was leer ist:',
  'onboarding.draft.firmLabel': 'Firma',
  'onboarding.draft.preset': 'Was passt am besten zu {name}? Ich nehme dafür die üblichen Antworten; du siehst sie am Schluss und kannst jede ändern.',
  'onboarding.draft.vat': 'Jetzt zur MWST. Die frage ich einzeln, weil sie die ganze Buchhaltung bestimmt.',
  'onboarding.draft.netRates': 'Welche Saldosteuersätze hat dir die ESTV bewilligt? Einen oder zwei.',
  'onboarding.draft.banks': 'Über welche Bankkonten läuft das Geld der Firma? Die IBAN kannst du auch später eintragen.',
  'onboarding.draft.review': 'Das ist alles, was ich zum Anlegen brauche. Danach bleibt wenig: was die Firma am 1. Januar hatte (die Eröffnung) und woher die Belege kommen.',
  'onboarding.draft.reviewTitle': 'Deine Buchhaltung',
  'onboarding.draft.creating': 'Wird angelegt …',
  'onboarding.draft.later': 'Später weitermachen',
  'onboarding.draft.laterHint': 'Was du beantwortet hast, bleibt im Ordner.',
  'onboarding.draft.next': 'Weiter',
  'onboarding.draft.none': 'keine',
  'onboarding.draft.noVat': 'Die Firma rechnet keine MWST ab: Käufe und Verkäufe werden ohne MWST gebucht, Rechnungen der App tragen keine MWST, und es gibt keine Abrechnung.',
  'onboarding.draft.periodUnusual.net-rate': 'Quartalsweise gilt beim Saldosteuersatz nur, wenn die ESTV es dir bewilligt hat; üblich ist halbjährlich. Bist du nicht sicher: «Ändern» und halbjährlich wählen.',
  'onboarding.draft.periodUnusual.effective': 'Halbjährlich gilt bei der effektiven Methode nur, wenn die ESTV es dir bewilligt hat; üblich ist quartalsweise. Bist du nicht sicher: «Ändern» und quartalsweise wählen.',
  'onboarding.draft.unsure': 'Weiss nicht (dann: {answer})',
  'onboarding.draft.assumed': 'angenommen',
  'onboarding.draft.assumedWhy': 'Nicht von dir gesagt: üblich bei {preset}',
  'onboarding.draft.assumedNote': 'Was «angenommen» trägt, hast du nicht gesagt: so ist es üblich bei {preset}. Stimmt etwas nicht, klick daneben auf «Ändern».',
  'onboarding.draft.assumedNoteBare': 'Was «angenommen» trägt, hast du nicht gesagt. Stimmt etwas nicht, klick daneben auf «Ändern».',
  'onboarding.assumedBooks': 'Angenommen, weil es bei {preset} üblich ist: du hast es nicht gesagt. Trifft es zu, klick «stimmt». Hat eine Antwort etwas eingerichtet, führt der Link daneben dorthin.',
  'onboarding.assumedBooksBare': 'Angenommen: du hast es nicht gesagt. Trifft es zu, klick «stimmt». Hat eine Antwort etwas eingerichtet, führt der Link daneben dorthin.',
  'onboarding.assumedNone': 'keine',
  'onboarding.assumedOk': 'stimmt',
  'onboarding.assumedCount': { one: '{n} Antwort angenommen', other: '{n} Antworten angenommen' },
  'onboarding.assumedSee': 'ansehen',
  'onboarding.assumedGo.ownerAccount': 'Konto des Inhabers unter {place}',
  'onboarding.assumedGo.accounts': 'Konten dafür unter {place}',
  'onboarding.assumedGo.opening': 'Eröffnung unter {place}',
  'onboarding.assumedGo.ownUse': 'Eigenverbrauch als Regel unter {place}',
