  'onboarding.draft.phase.firm': 'Firma',
  'onboarding.draft.phase.kind': 'Art der Firma',
  'onboarding.draft.phase.vat': 'MWST',
  'onboarding.draft.phase.banks': 'Bank',
  'onboarding.talk.placeholder': 'Antworte mit den Knöpfen oder schreib es in deinen Worten, z. B. «Schreinerei in Bern, GmbH, zwei Angestellte»',
  'onboarding.talk.label': 'Nachricht an die Einrichtung',
  'onboarding.talk.fromText': 'aus deiner Nachricht',
  'onboarding.talk.reading': 'Ich lese deine Nachricht …',
  'onboarding.talk.filled': 'Aus deiner Nachricht übernommen:',
  'onboarding.talk.refused': 'Nicht übernommen: {why}',
  'onboarding.talk.notStated.uid': 'Die UID {detail} steht nicht in deinen Worten. Eine UID übernehme ich nur so, wie du sie schreibst.',
  'onboarding.talk.notStated.iban': 'Die IBAN {detail} steht nicht in deinen Worten. Eine IBAN übernehme ich nur so, wie du sie schreibst.',
  'onboarding.talk.notAnOption': '{question}: «{value}» gibt es hier nicht. Wähl eine der Antworten.',
  'onboarding.talk.noVat': 'Dass die Firma keine MWST abrechnet, übernehme ich nicht aus deinen Worten: das wählst du selbst, mit «nein» bei «Im MWST-Register eingetragen?» oder mit «Wir rechnen keine MWST ab». Ist die Firma eingetragen und du kennst die Methode nicht, frag deine Treuhand.',
  'onboarding.talk.unusualPeriod.net-rate': 'Quartalsweise abrechnen ist beim Saldosteuersatz unüblich: üblich ist halbjährlich. Quartalsweise gilt nur, wenn die ESTV es dir bewilligt hat; dann wähl es bei der Frage «Abrechnungsperiode» mit dem Knopf.',
  'onboarding.talk.unusualPeriod.effective': 'Halbjährlich abrechnen ist bei der effektiven Methode unüblich: üblich ist quartalsweise. Halbjährlich gilt nur, wenn die ESTV es dir bewilligt hat; dann wähl es bei der Frage «Abrechnungsperiode» mit dem Knopf.',
  'onboarding.talk.unreadable': 'Die Antwort der KI konnte ich nicht lesen, darum ist nichts geändert. Schreib es nochmals oder wähl die Antwort mit den Knöpfen.',
  'onboarding.talk.failed': 'Die KI hat nicht geantwortet ({detail}), darum ist nichts geändert. Die Knöpfe und Felder gehen weiterhin.',
  'onboarding.talk.nothing': 'Darin finde ich keine Antwort für die Einrichtung.',
  'onboarding.talk.reviewNote': 'Was «aus deiner Nachricht» trägt, habe ich deinen Worten entnommen. Schau es an, bevor du die Buchhaltung anlegst.',
  'onboarding.s.hello': 'Hallo. Die Buchhaltung ist angelegt. Es bleibt wenig: was die Firma am 1. Januar hatte und woher die Belege kommen. Du antwortest mit einem Klick oder in deinen Worten.',
  'onboarding.s.helloNoAi': 'Hallo. Die Buchhaltung ist angelegt. Es bleibt wenig: was die Firma am 1. Januar hatte und woher die Belege kommen. Du antwortest mit einem Klick.',
  'onboarding.s.company': 'Das weiss die App schon über die Firma, darum frage ich es nicht nochmals:',
  'onboarding.q.company.ok': 'Stimmt so',
  'onboarding.q.company.fix': 'Etwas ändern',
  'onboarding.r.companyFix': 'Name, UID und Adresse änderst du unter Firma › Firma. Die MWST und was ihr verkauft, frage ich gleich hier:',
  'onboarding.s.vat': 'Wie rechnest du die MWST ab?',
  'onboarding.q.vat.none': 'Wir rechnen keine MWST ab',
  'onboarding.q.vat.none.sub': 'nur ohne Eintrag im MWST-Register; eingetragen und unsicher: frag deine Treuhand',
  'onboarding.q.vat.effective': 'Effektiv, pro Quartal',
  'onboarding.q.vat.effective.sub': 'das Übliche: MWST abzüglich Vorsteuer',
  'onboarding.q.vat.net-rate': 'Saldosteuersatz, pro Halbjahr',
  'onboarding.q.vat.net-rate.sub': 'ein bewilligter Satz auf dem Umsatz, ohne Vorsteuer',
  'onboarding.q.vat.unknown': 'Weiss nicht',
  'onboarding.q.vat.unknown.sub': 'dann bleibt es, wie es eingetragen ist',
  'onboarding.r.vatSame': 'So ist es eingetragen. Abgerechnet wird nach vereinnahmten Entgelten, also wenn bezahlt ist, nicht wenn verrechnet. Wenn das bei dir anders ist, sag es.',
  'onboarding.r.vatSameAgreed': 'So ist es eingetragen. Abgerechnet wird nach vereinbarten Entgelten, also wenn verrechnet ist, nicht wenn bezahlt. Wenn das bei dir anders ist, sag es.',
  'onboarding.r.vatSameNone': 'So ist es eingetragen: keine MWST-Abrechnung, alles wird brutto gebucht. Unter MWST zeigt die App, wie nahe dein Umsatz an der Grenze zur Pflicht liegt.',
  'onboarding.r.vatUnknown': 'Dann bleibt es vorerst, wie es eingetragen ist. Deine letzte MWST-Abrechnung sagt es: leg sie hier ab, dann lese ich sie und sage dir, ob etwas anders ist.',
  'onboarding.r.vatChange': 'Dann ändere ich die Einstellung. Sie gilt erst, wenn du sie übernimmst:',
  'onboarding.s.openingSet': 'Die Eröffnung per {date} ist erfasst:',
  'onboarding.s.openingNone': 'Die Eröffnung ist, was die Firma am {date} hatte: Geld auf der Bank, offene Rechnungen, Schulden (die Eröffnungsbilanz). Sie gilt immer per {date}: nimm alle Zahlen, auch den Stand des Bankkontos, aus der Bilanz per {prev}. Eine neue Firma trägt das einbezahlte Kapital ein.',
  'onboarding.s.openingNoneSwitching': 'Die Eröffnung ist, was die Firma am {date} hatte: Geld auf der Bank, offene Rechnungen, Schulden (die Eröffnungsbilanz). Sie gilt immer per {date}: nimm alle Zahlen, auch den Stand des Bankkontos, aus der Bilanz per {prev}, der letzten deiner bisherigen Buchhaltung.',
  'onboarding.q.opening.next': 'Weiter',
  'onboarding.q.opening.later': 'Später',
  'onboarding.r.openingLater': 'Gut. Bis die Eröffnung erfasst ist, weicht der Kontostand in der App um den Anfangsbestand von dem der Bank ab. Du trägst sie unter Firma › Eröffnung ein; beim ersten Kontoauszug führt «Eröffnung erfassen» dorthin.',
  'onboarding.opening.account': 'Konto',
  'onboarding.opening.amount': 'Saldo',
  'onboarding.s.bank': 'Diese Bankkonten kennt die App:',
  'onboarding.s.bankNone': 'Noch hat kein Bankkonto eine IBAN. Mit der IBAN ordnet die App jeden Kontoauszug dem richtigen Konto zu.',
  'onboarding.q.bank.next': 'Weiter',
  'onboarding.q.bank.later': 'Später',
  'onboarding.banks.iban': 'IBAN',
  'onboarding.banks.noIban': 'ohne IBAN',
  'onboarding.banks.none': 'Noch keines.',
  'onboarding.banks.statements': 'Kontoauszüge (camt.053 oder PDF) ziehst du in die App, oder eine Quelle holt sie.',
  'onboarding.banks.add': 'Bankkonto erfassen',
  'onboarding.s.receipts': 'So kommen Belege von selbst herein:',
  'onboarding.s.receiptsNone': 'Noch kommt kein Beleg von selbst. Am einfachsten ist ein Postfach, an das du Belege weiterleitest; ich richte es mit dir ein.',
  'onboarding.s.receiptsNoneNoAi': 'Noch kommt kein Beleg von selbst. Bis dahin ziehst du Belege in die App, aus dem Finder oder aus einer Mail.',
  'onboarding.q.receipts.next': 'Weiter',
  'onboarding.q.receipts.later': 'Später',
  'onboarding.sources.on': 'eingeschaltet',
  'onboarding.sources.none': 'Noch keine Quelle eingeschaltet.',
  'onboarding.sources.ask': 'Mit mir einrichten',
  'onboarding.sources.noAi': 'Im Gespräch einrichten geht erst mit einer KI.',
  'onboarding.sources.lookFailed': 'Ob hier eine KI antwortet, konnte die App nicht prüfen ({why}); sie prüft es wieder, wenn du zum Fenster zurückkommst.',
  'onboarding.sources.askText': 'Richte mit mir ein, wie meine Belege hereinkommen.',
  'onboarding.sources.show': 'Quellen ansehen',
