  'aiSetup.key.intro': 'Statt eines Abos geht auch ein API-Schlüssel von Anthropic oder OpenAI. Der Anbieter rechnet jeden Aufruf ab, auf deine Rechnung; wie viel, hängt davon ab, wie viele Belege die App liest. Empfohlen bleibt ein Abo: Claude Pro oder ChatGPT Plus, etwa 20 USD im Monat, ohne Rechnung pro Aufruf.',
  'aiSetup.key.firmaIntro': 'Statt eines Abos oder dazu. Der Anbieter rechnet jeden Aufruf ab, auf deine Rechnung. Ohne angemeldetes Claude Code oder Codex stellt die App alle Schritte auf den Schlüssel, ausser der KI-Spalte; mit einem der beiden nur die Schritte, die du unten auf ihn stellst.',
